def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    players = 1 + len(alive)
    expected_units = supply / float(WATER_REQ)

    prev_bids = []
    stressed_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            stressed_opp += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    scarcity = players - expected_units

    if hp <= 2 or no_water_days >= 2:
        emergency = 1.0
    elif hp <= 4 or no_water_days >= 1:
        emergency = 0.7
    else:
        emergency = 0.0

    if scarcity >= 2:
        base = DAILY_SALARY * 0.82
    elif scarcity >= 1:
        base = DAILY_SALARY * 0.68
    elif scarcity >= 0:
        base = DAILY_SALARY * 0.56
    else:
        base = DAILY_SALARY * 0.38

    base += stressed_opp * 2.5
    base += rich_opp * 1.0

    if highest_prev > 0:
        if emergency >= 0.7:
            target = max(base, highest_prev + 3.0)
        elif highest_prev >= DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.34 if hp > 4 and no_water_days == 0 else DAILY_SALARY * 0.93
        else:
            target = max(base, avg_prev + 1.5, highest_prev + 1.0)
    else:
        target = base

    if day >= 8:
        target += 4.0
    if day >= 9:
        target += 4.0

    if emergency == 1.0:
        target = max(target, DAILY_SALARY * 0.95)
    elif emergency >= 0.7:
        target = max(target, DAILY_SALARY * 0.8)

    if budget < DAILY_SALARY * 0.6:
        target = min(target, budget)
    elif budget < DAILY_SALARY:
        target = min(target, DAILY_SALARY * 0.78)

    if not alive:
        target = min(target, DAILY_SALARY * 0.35)

    if target < 0:
        target = 0
    if target > budget:
        target = budget

    return float(target)

