    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Immediate reaction to yesterday's behavior (only previous_trace)
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how contested the market is
    if prev_bids:
        highest_prev_bid = max(prev_bids)
    else:
        highest_prev_bid = 0.0

    # Supply-aware baseline: if supply is tight, bid a bit more; if ample, stay moderate.
    # (Use thresholds aligned with provided supply range 15-25.)
    if supply <= 16.0:
        base = DAILY_SALARY * 0.65
    elif supply >= 24.0:
        base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.55

    # If an opponent previously bid very high, match pressure to prevent them from cornering.
    # Keep this conservative to avoid budget depletion.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp > 3:
            target = max(base, DAILY_SALARY * 0.70)
        else:
            target = max(base, DAILY_SALARY * 0.92)
    elif highest_prev_bid >= DAILY_SALARY * 0.60:
        target = max(base, highest_prev_bid + 1.0)
    else:
        target = base

    # If low HP, increase bids to reduce risk of no-water days.
    if my_hp <= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 3:
        target = max(target, DAILY_SALARY * 0.70)

    # Budget cap and mild safety margin.
    # Also ensure bid is not wildly above what would be needed relative to supply.
    # Convert supply to an approximate max competitive bid scale.
    # Use int() to satisfy index safety rule even though we don't index.
    _ = int(WATER_REQ)  # explicit int use

    bid = min(my_budget, target)
    if bid < 0:
        bid = 0
    return bid
